/**
 * Prompt bank, transcribed verbatim from "L5 Prompt bank by mood" (Figma node
 * 23:23) — a frame the designer labelled "Reference sheet — not a user-facing
 * screen".
 *
 * L5 also notes these are "Generated by Claude API from mood + recent entries",
 * so in production the bank is dynamic and the follow-up reacts to what the user
 * just wrote. Until that API exists, step 1 uses the first prompt for the mood
 * and step 2 the second, and "Ask me something else" cycles between them.
 */
export const PROMPTS = {
	Rough: [
		'What was the hardest part of today — the training itself, or something else?',
		'Is this a one-off bad day, or has it been building up?',
	],
	Mixed: [
		'What was one thing today that went better than you expected?',
		'If tomorrow could go slightly differently, what would change?',
	],
	Okay: [
		'Anything from today worth remembering when a harder week comes?',
		'Who or what made today more manageable?',
	],
	Good: [
		"What clicked today that hadn't before?",
		"Is there someone in your section you'd want to tell about this?",
	],
};

/**
 * Chip fill for the "Today: <mood>" tag (node 22:11). L1 only ever shows Rough,
 * in accent; these follow the colour L5 gives each mood's heading, which agrees
 * with that one frame.
 */
export const MOOD_CHIP_BG = {
	Rough: 'bg-accent',
	Mixed: 'bg-warn',
	Okay: 'bg-calm',
	Good: 'bg-calm',
};

/** Mixed's amber needs dark text to stay legible; the others are dark fills. */
export const MOOD_CHIP_TEXT = {
	Rough: 'text-white',
	Mixed: 'text-ink',
	Okay: 'text-white',
	Good: 'text-white',
};

